function pageSize(input) {
  const size = input ?? 25;
  if (!Number.isInteger(size) || size < 0) throw new RangeError("invalid size");
  return size;
}

console.assert(pageSize(0) === 0);
console.assert(pageSize(undefined) === 25);

async function mapLimit(values, limit, work) {
  const output = new Array(values.length);
  let next = 0;
  async function worker() {
    while (next < values.length) {
      const index = next++;
      output[index] = await work(values[index]);
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, values.length) }, worker));
  return output;
}

