type Job =
  | { state: "queued"; position: number }
  | { state: "running"; startedAt: Date }
  | { state: "failed"; error: Error }
  | { state: "done"; result: string };

function assertNever(value: never): never {
  throw new Error(`Unhandled job: ${JSON.stringify(value)}`);
}

function label(job: Job): string {
  switch (job.state) {
    case "queued": return `#${job.position}`;
    case "running": return job.startedAt.toISOString();
    case "failed": return job.error.message;
    case "done": return job.result;
    default: return assertNever(job);
  }
}

type Port = number & { readonly __brand: unique symbol };

function parsePort(value: unknown): Port {
  if (typeof value !== "number" || !Number.isInteger(value) || value < 1 || value > 65535) {
    throw new TypeError("port must be an integer from 1 to 65535");
  }
  return value as Port;
}

const port = parsePort(JSON.parse("8080"));

